const voicedRows=[['がぎぐげご','ガギグゲゴ',['ga','gi','gu','ge','go']],['ざじずぜぞ','ザジズゼゾ',['za','ji','zu','ze','zo']],['だぢづでど','ダヂヅデド',['da','ji','zu','de','do']],['ばびぶべぼ','バビブベボ',['ba','bi','bu','be','bo']],['ぱぴぷぺぽ','パピプペポ',['pa','pi','pu','pe','po']]];
